// Works with Simplify Output on (answers under data) or off (a field_data list).
const settings = $('Settings').first().json;
const cc = String(settings.defaultCountryCode || '').replace(/\D/g, '');
const known = ['full_name', 'name', 'first_name', 'last_name', 'email', 'work_email', 'phone_number', 'phone', 'mobile_number'];
const out = [];

for (const item of $('New Lead').all()) {
  const l = item.json;
  const a = {};
  if (l.data && typeof l.data === 'object') Object.assign(a, l.data);
  else if (Array.isArray(l.field_data)) {
    for (const f of l.field_data) a[f.name] = Array.isArray(f.values) ? f.values[0] : f.values;
  }
  const pick = (...keys) => {
    for (const k of keys) {
      const v = a[k];
      if (v != null && String(v).trim()) return String(v).trim();
    }
    return '';
  };

  const fullName = pick('full_name', 'name') || [pick('first_name'), pick('last_name')].filter(Boolean).join(' ');
  const email = pick('email', 'work_email').toLowerCase();
  const typed = pick('phone_number', 'phone', 'mobile_number');
  const digits = typed.replace(/[^\d+]/g, '');
  let phone = '';
  if (digits.startsWith('+')) phone = '+' + digits.slice(1).replace(/\D/g, '');
  else if (digits.startsWith('00')) phone = '+' + digits.slice(2);
  else if (digits.startsWith('0') && cc) phone = '+' + cc + digits.slice(1);
  else if (digits && cc && digits.startsWith(cc)) phone = '+' + digits;
  else if (digits && cc) phone = '+' + cc + digits;
  else phone = digits;

  const answers = Object.entries(a)
    .filter(([k, v]) => !known.includes(k) && v != null && String(v).trim())
    .map(([k, v]) => k.replace(/_/g, ' ') + ': ' + String(v).trim())
    .join('; ');

  // Meta's Lead Ads Testing Tool fills every field with "<test lead: dummy data for ...>".
  const isTest = Object.values(a).some(v => /test lead|dummy data/i.test(String(v ?? '')));

  out.push({ json: {
    lead_id: String(l.id ?? ''),
    received_at: new Date().toISOString(),
    created_time: l.created_time ? new Date(l.created_time).toISOString() : '',
    full_name: fullName,
    email,
    phone,
    phone_as_typed: typed,
    form: (l.form && (l.form.name || l.form.id)) || '',
    ad: (l.ad && (l.ad.name || l.ad.id)) || '',
    answers,
    is_test: isTest,
  } });
}
return out;

// Decides what each lead is before anything is written: test, repeat, new, or a redelivery.
const settings = $('Settings').first().json;
const days = Number(settings.duplicateWindowDays) || 30;
const cutoff = Date.now() - days * 86400000;
const digitsOnly = v => String(v ?? '').replace(/\D/g, '');

const loggedIds = new Set();
const lastSeen = new Map();
const remember = (key, when) => {
  if (!key) return;
  if (!lastSeen.has(key) || lastSeen.get(key) < when) lastSeen.set(key, when);
};

for (const r of $('Read Recent Leads').all().map(i => i.json)) {
  if (!r) continue;
  if (r.lead_id) loggedIds.add(String(r.lead_id));
  if (String(r.status) === 'test') continue;
  const when = Date.parse(r.received_at || r.created_time || '') || 0;
  if (!when || when < cutoff) continue;
  remember('e:' + String(r.email ?? '').trim().toLowerCase().replace(/^e:$/, ''), when);
  remember('p:' + digitsOnly(r.phone), when);
}
lastSeen.delete('e:');
lastSeen.delete('p:');

const out = [];
// This node sits after the sheet read, so the leads are fetched from the normaliser by name.
for (const item of $('Normalise Lead Fields').all()) {
  const lead = item.json;
  // Meta retries a webhook it thinks failed. Same lead id means it is already in the sheet.
  if (lead.lead_id && loggedIds.has(lead.lead_id)) continue;
  const keys = [lead.email ? 'e:' + lead.email : '', digitsOnly(lead.phone) ? 'p:' + digitsOnly(lead.phone) : ''].filter(Boolean);
  const previous = keys.map(k => lastSeen.get(k)).filter(Boolean).sort((x, y) => y - x)[0];
  const status = lead.is_test ? 'test' : previous ? 'repeat' : 'new';
  if (!lead.is_test) keys.forEach(k => remember(k, Date.now()));
  if (lead.lead_id) loggedIds.add(lead.lead_id);
  out.push({ json: { ...lead, status, previous_lead_at: previous ? new Date(previous).toISOString() : '' } });
}
return out;
